(async function live(){
  const badge = document.createElement("button");
  badge.className = "tab"; badge.id = "live-badge";
  badge.style.cssText = "margin-left:8px;cursor:default";
  let seen = null, fails = 0;

  async function poll(){
    try{
      const r = await fetch("/live.json", {cache:"no-store"});
      if(!r.ok) throw new Error(r.status);
      const s = await r.json();
      fails = 0;
      if(!document.getElementById("live-badge"))
        document.querySelector(".nav-in").appendChild(badge);
      if(s.status && s.status.startsWith("error")){
        badge.innerHTML = `<span class="livedot warn"><i></i>SWEEP FAILED</span>`;
        badge.title = s.status;
      } else {
        badge.innerHTML = `<span class="livedot"><i></i>LIVE · ${s.sides_in_flight} in flight</span>`;
        badge.title = `last sweep ${(s.generated||"").slice(11,19)}`;
      }
      const stamp = JSON.stringify([s.generated, s.flights.map(f=>[f.intent,f.files,f.uncommitted_lines]),
                                    s.pairs.map(p=>p.result&&p.result.verdict)]);
      if(stamp === seen) return;
      const first = seen === null;
      seen = stamp;
      DB = Object.assign({}, DATA, s);
      renderAll();
      if(!first) toast(`Airspace updated — ${s.sides_in_flight} agent(s) in flight`);
    }catch(e){
      if(++fails === 1 && document.getElementById("live-badge"))
        badge.innerHTML = `<span class="livedot warn"><i></i>WATCHER OFFLINE</span>`;
    }
  }
  await poll();                       // static file: fails once, silently
  if(fails === 0) setInterval(poll, 4000);
})();

